//! Development IPC shared by the GUI and the session service. No GUI or FFI dependencies.
//! The app and core evolve together; wire compatibility is not maintained during development.
use serde::{Deserialize, Serialize};
use std::io::{self, Read, Write};
use std::path::PathBuf;

pub const MAX_MESSAGE: usize = 16 * 1024 * 1024;
pub const MAX_INPUT: usize = 256 * 1024;
/// A native key event carries only the short text generated by one key press.
pub const MAX_KEY_TEXT: usize = 4 * 1024;
pub const MAX_COLS: u16 = 300;
pub const MAX_ROWS: u16 = 120;
pub const MAX_WORKSPACES: usize = 16;
pub const MAX_TERMINALS: usize = 64;
/// Bound frames per tab; a client view includes the active tab and, optionally, one preview tab.
pub const MAX_PANES_PER_TAB: usize = 8;
pub type WorkspaceId = u64;
pub type TerminalId = u64;

/// Horizontal splits stack panes top/bottom; vertical splits place them side by side.
#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum SplitDirection {
    Horizontal,
    Vertical,
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum PanePlacement {
    Swap,
    Left,
    Right,
    Top,
    Bottom,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum PaneLayout {
    Leaf {
        terminal_id: TerminalId,
    },
    Split {
        direction: SplitDirection,
        first: Box<PaneLayout>,
        second: Box<PaneLayout>,
    },
}

impl PaneLayout {
    pub fn terminal_ids(&self) -> Vec<TerminalId> {
        let mut ids = Vec::new();
        self.collect_terminal_ids(&mut ids);
        ids
    }

    pub fn contains(&self, id: TerminalId) -> bool {
        match self {
            Self::Leaf { terminal_id } => *terminal_id == id,
            Self::Split { first, second, .. } => first.contains(id) || second.contains(id),
        }
    }

    fn collect_terminal_ids(&self, ids: &mut Vec<TerminalId>) {
        match self {
            Self::Leaf { terminal_id } => ids.push(*terminal_id),
            Self::Split { first, second, .. } => {
                first.collect_terminal_ids(ids);
                second.collect_terminal_ids(ids);
            }
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct TabInfo {
    /// Stable tab identity, initially equal to the tab's first terminal ID.
    pub id: TerminalId,
    pub layout: PaneLayout,
}

#[derive(Clone, Copy, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
#[repr(u8)]
pub enum UnderlineStyle {
    #[default]
    None = 0,
    Single = 1,
    Double = 2,
    Curly = 3,
    Dotted = 4,
    Dashed = 5,
}

impl UnderlineStyle {
    pub fn is_none(self) -> bool {
        self == Self::None
    }
}

fn is_false(value: &bool) -> bool {
    !*value
}

#[derive(Clone, Debug, Serialize, PartialEq)]
pub struct Cell {
    pub text: String,
    /// Display columns: 0 for the continuation of a wide glyph, otherwise 1 or 2.
    pub width: u8,
    /// Ghostty's empty end-of-row placeholder when a wide glyph moves to the next row.
    #[serde(default, skip_serializing_if = "is_false")]
    pub wide_spacer_head: bool,
    pub fg: [u8; 3],
    pub bg: [u8; 3],
    pub bold: bool,
    pub italic: bool,
    #[serde(default)]
    pub faint: bool,
    #[serde(default)]
    pub blink: bool,
    #[serde(default)]
    pub concealed: bool,
    #[serde(default)]
    pub strikethrough: bool,
    #[serde(default)]
    pub overline: bool,
    /// Underline style. Legacy boolean IPC values decode as single/none.
    pub underline: UnderlineStyle,
    /// Resolved underline RGB. An unset SGR underline color follows the resolved foreground.
    pub underline_color: [u8; 3],
}

impl<'de> Deserialize<'de> for Cell {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum UnderlineValue {
            Legacy(bool),
            Style(UnderlineStyle),
        }

        fn underline<'de, D>(deserializer: D) -> Result<UnderlineStyle, D::Error>
        where
            D: serde::Deserializer<'de>,
        {
            Ok(match UnderlineValue::deserialize(deserializer)? {
                UnderlineValue::Legacy(false) => UnderlineStyle::None,
                UnderlineValue::Legacy(true) => UnderlineStyle::Single,
                UnderlineValue::Style(style) => style,
            })
        }

        #[derive(Deserialize)]
        struct Wire {
            text: String,
            width: u8,
            #[serde(default)]
            wide_spacer_head: bool,
            fg: [u8; 3],
            bg: [u8; 3],
            bold: bool,
            italic: bool,
            #[serde(default)]
            faint: bool,
            #[serde(default)]
            blink: bool,
            #[serde(default)]
            concealed: bool,
            #[serde(default)]
            strikethrough: bool,
            #[serde(default)]
            overline: bool,
            #[serde(default, deserialize_with = "underline")]
            underline: UnderlineStyle,
            #[serde(default)]
            underline_color: Option<[u8; 3]>,
        }

        let wire = Wire::deserialize(deserializer)?;
        Ok(Self {
            text: wire.text,
            width: wire.width,
            wide_spacer_head: wire.wide_spacer_head,
            fg: wire.fg,
            bg: wire.bg,
            bold: wire.bold,
            italic: wire.italic,
            faint: wire.faint,
            blink: wire.blink,
            concealed: wire.concealed,
            strikethrough: wire.strikethrough,
            overline: wire.overline,
            underline: wire.underline,
            underline_color: wire.underline_color.unwrap_or(wire.fg),
        })
    }
}

