/// A Ghostty/W3C physical key code when Rune supplied one for this native event.
/// Values are the contiguous public `GhosttyKey` range, excluding unidentified (zero).
#[derive(Clone, Copy, Debug, Serialize, PartialEq, Eq)]
#[serde(transparent)]
pub struct PhysicalKey(u16);

impl PhysicalKey {
    pub const fn new(value: u16) -> Option<Self> {
        if value >= 1 && value <= 175 {
            Some(Self(value))
        } else {
            None
        }
    }

    pub const fn value(self) -> u16 {
        self.0
    }
}

impl<'de> Deserialize<'de> for PhysicalKey {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let value = u16::deserialize(deserializer)?;
        Self::new(value).ok_or_else(|| serde::de::Error::custom("invalid physical key code"))
    }
}

#[derive(Clone, Copy, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct KeyModifiers {
    pub shift: bool,
    pub alt: bool,
    pub ctrl: bool,
    pub super_key: bool,
}

/// Structured native key input. IME commits and explicitly scripted byte streams use `Input`.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct KeyInput {
    pub action: KeyAction,
    pub key: TerminalKey,
    pub physical: Option<PhysicalKey>,
    pub text: String,
    pub modifiers: KeyModifiers,
}

impl KeyInput {
    pub fn validate(&self) -> Result<(), &'static str> {
        if self.text.len() > MAX_KEY_TEXT {
            return Err("key text is too large");
        }
        if matches!(self.key, TerminalKey::Function { number: 0 | 25.. }) {
            return Err("function key is outside F1-F24");
        }
        if self.key == TerminalKey::Character {
            if self.text.is_empty() {
                return Err("character key text is empty");
            }
            if self
                .text
                .chars()
                .any(|c| c <= '\u{1f}' || c == '\u{7f}' || ('\u{f700}'..='\u{f8ff}').contains(&c))
            {
                return Err("key text contains a control or platform function code");
            }
        } else if !self.text.is_empty() {
            return Err("named key unexpectedly contains text");
        }
        Ok(())
    }
}

/// Cursor geometry requested by the terminal application (DECSCUSR).
#[derive(Clone, Copy, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum CursorShape {
    #[default]
    Block,
    Bar,
    Underline,
    HollowBlock,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Screen {
    pub cols: u16,
    pub rows: u16,
    pub cells: Vec<Vec<Cell>>,
    /// Per-row flag indicating that the row continues onto the next physical row.
    /// Missing entries from older saved frames are hard breaks.
    #[serde(default)]
    pub row_soft_wrapped: Vec<bool>,
    pub cursor_x: u16,
    pub cursor_y: u16,
    pub cursor_visible: bool,
    #[serde(default)]
    pub cursor_shape: CursorShape,
    #[serde(default)]
    pub cursor_blinking: bool,
    /// Explicit terminal cursor color (e.g. OSC 12), or the client's fallback.
    #[serde(default)]
    pub cursor_color: Option<[u8; 3]>,
    pub title: String,
    pub application_cursor: bool,
    pub bracketed_paste: bool,
    /// True while any terminal mouse tracking mode (X10/1000/1002/1003) is active.
    #[serde(default)]
    pub mouse_tracking: bool,
    /// Rows between this client's viewport and the live terminal area.
    #[serde(default)]
    pub scrollback_offset: u64,
}

impl Screen {
    pub fn is_row_soft_wrapped(&self, row: usize) -> bool {
        self.row_soft_wrapped.get(row).copied().unwrap_or(false)
    }
}

